lemma aestronglyMeasurable_iInf_of_antitone
    {α : Type*} {m₀ : MeasurableSpace α} {μ : @MeasureTheory.Measure α m₀}
    {m : ℕ → MeasurableSpace α}
    (h_anti : Antitone m)
    (f : α → β)
    (hf : ∀ N, @MeasureTheory.AEStronglyMeasurable α β _ (m N) m₀ f μ) :
    @MeasureTheory.AEStronglyMeasurable α β _ (⨅ N, m N) m₀ f μ

lemma aestronglyMeasurable_of_tendsto_ae'
    {α : Type*} {m₀ : MeasurableSpace α} {μ : @MeasureTheory.Measure α m₀}
    {m : MeasurableSpace α}
    {f : ℕ → α → β} {g : α → β}
    (hf : ∀ n, @MeasureTheory.AEStronglyMeasurable α β _ m m₀ (f n) μ)
    (hlim : ∀ᵐ x ∂μ, Filter.Tendsto (fun n => f n x) Filter.atTop (nhds (g x))) :
    @MeasureTheory.AEStronglyMeasurable α β _ m m₀ g μ

theorem memLp_comp_of_bound {μ : Measure Ω} [IsFiniteMeasure μ] {g : Ω → α} {f : α → E}
    (hf : Measurable f) (hg : AEMeasurable g μ) (C : ℝ) (hbound : ∀ᵐ ω ∂μ, ‖f (g ω)‖ ≤ C)
    (p : ENNReal) : MemLp (fun ω => f (g ω)) p μ

theorem Integrable.exp_abs_smul_of_ae_abs_le {μ : Measure ℝ} {g : ℝ → β}
    (hg : Integrable g μ) (a R : ℝ) (hR : ∀ᵐ x ∂μ, |x| ≤ R) :
    Integrable (fun x : ℝ => (Real.exp (a * |x|) : 𝕜) • g x) μ

def lpBilinearForm (μ : Measure X)
    (B : Lp (J →L[ℝ] J →L[ℝ] ℝ) ⊤ μ) :
    Lp J 2 μ →L[ℝ] Lp J 2 μ →L[ℝ] ℝ

theorem lpBilinearForm_congr_ae {μ : Measure X}
    {B B' : Lp (J →L[ℝ] J →L[ℝ] ℝ) ⊤ μ} (hB : B =ᵐ[μ] B') :
    lpBilinearForm μ B = lpBilinearForm μ B'

theorem integrable_bilinear_apply_of_memLp {μ : Measure X}
    {B : X → J →L[ℝ] J →L[ℝ] ℝ} (hB : MemLp B ⊤ μ) (U V : Lp J 2 μ) :
    Integrable (fun x => B x (U x) (V x)) μ

theorem setIntegral_eq_zero_of_isPiSystem {X E : Type*} {m0 : MeasurableSpace X}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {ρ : Measure X} {S : Set (Set X)}
    (hgen : m0 = MeasurableSpace.generateFrom S) (hpi : IsPiSystem S) {f : X → E}
    (hf : Integrable f ρ) (huniv : ∫ x, f x ∂ρ = 0) (hS : ∀ s ∈ S, ∫ x in s, f x ∂ρ = 0) :
    ∀ u, MeasurableSet u → ∫ x in u, f x ∂ρ = 0

theorem measurable_probabilityMeasure_eval_family {ι : Type*}
    (B : ι → Set α) (hB : ∀ i, MeasurableSet (B i)) :
    Measurable fun P : ProbabilityMeasure α => fun i => (P (B i) : ℝ)

theorem measurable_probabilityMeasure_pi_const_toMeasure {α : Type*} [MeasurableSpace α] {m : ℕ}
    (ν : Ω → ProbabilityMeasure α) (hν : Measurable ν) :
    Measurable fun ω => (ProbabilityMeasure.pi fun _ : Fin m => ν ω).toMeasure

theorem aemeasurable_probabilityMeasure_pi_const_toMeasure {α : Type*} [MeasurableSpace α] {m : ℕ}
    (ν : Ω → ProbabilityMeasure α) (hν : AEMeasurable ν μ) :
    AEMeasurable (fun ω => (ProbabilityMeasure.pi fun _ : Fin m => ν ω).toMeasure) μ
